import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import {Suspense, useState} from 'react'

import {getEditCloudProfileUrl} from './CloudProfileError.utils'

import styles from './CloudProfileError.module.css'

import Alert, {AlertType} from 'src/components/common/Alert/Alert'
import ErrorBoundary from 'src/components/common/ErrorBoundary/ErrorBoundary'
import {usePermission} from 'src/hooks/usePermission'
import {Permission, type ProjectId} from 'src/types'

type CloudProfileSettingsLinkProps = {
  inline?: boolean
  projectId: string
  cloudProfileId: string
}
function CloudProfileSettingsLink({
  inline,
  projectId,
  cloudProfileId,
}: CloudProfileSettingsLinkProps) {
  return (
    <Button
      href={getEditCloudProfileUrl(projectId, cloudProfileId)}
      height={inline ? undefined : ControlsHeight.M}
      inline={inline}
      primary={inline}
    >
      {'Open profile settings'}
    </Button>
  )
}

type CloudProfileErrorProps = {
  message: string
  details?: string | null
  projectId?: ProjectId | null
  cloudProfileId?: string | null
  className?: string
}
function CloudProfileError({
  className,
  message,
  details,
  projectId,
  cloudProfileId,
}: CloudProfileErrorProps) {
  const canManageProfiles = usePermission(Permission.MANAGE_AGENT_CLOUDS, projectId)
  const shouldShowSettingsLink = projectId != null && cloudProfileId != null && canManageProfiles

  const [shouldShowStacktrace, setShouldShowStacktrace] = useState(false)
  const handleCloseClick = () => setShouldShowStacktrace(false)

  return (
    <>
      <Alert className={className} contentClassName={styles.content} type={AlertType.WARNING}>
        <div>
          <H3 className={styles.title}>{'Cloud profile error'}</H3>
          <div className={styles.text}>{message}</div>
        </div>
        <div className={styles.actions}>
          <Button onClick={() => setShouldShowStacktrace(true)} inline primary>
            {'Show stacktrace'}
          </Button>
          {shouldShowSettingsLink && (
            <CloudProfileSettingsLink
              projectId={projectId}
              cloudProfileId={cloudProfileId}
              inline
            />
          )}
        </div>
      </Alert>
      <Dialog
        contentClassName={styles.stacktraceDialog}
        show={shouldShowStacktrace}
        onCloseClick={handleCloseClick}
        showCloseButton
        dense
        closeButtonInside
      >
        <Header>{'Cloud profile error'}</Header>
        <Content>
          <div className={styles.error}>{message}</div>
          <pre className={styles.stacktrace}>{details}</pre>
        </Content>
        <Panel>
          <Button height={ControlsHeight.M} onClick={handleCloseClick} primary>
            {'Close'}
          </Button>
          {shouldShowSettingsLink && (
            <CloudProfileSettingsLink projectId={projectId} cloudProfileId={cloudProfileId} />
          )}
        </Panel>
      </Dialog>
    </>
  )
}

function CloudProfileErrorContainer(props: CloudProfileErrorProps) {
  return (
    <Suspense>
      <ErrorBoundary>
        <CloudProfileError {...props} />
      </ErrorBoundary>
    </Suspense>
  )
}

export default CloudProfileErrorContainer
